      "verdict": "contradicted",
      "evidence": "Range 0–72 and the billing rule suggest subscription duration, not customer age."
    },
    {
      "column": "PhoneService",
      "verdict": "plausible",
      "evidence": "Yes/No categories match phone service availability."
    },
    {
      "column": "MultipleLines",
