      "column": "Contract",
      "verdict": "plausible",
      "evidence": "Observed categories exactly match the three documented contract terms."
    },
    {
      "column": "PaperlessBilling",
      "verdict": "plausible",
      "evidence": "Yes/No categories match paperless billing enrollment."
    },
    {
      "column": "PaymentMethod",
