{
  "proposed_features": [
    {
      "name": "historical_average_monthly_charge",
      "op": "ratio",
      "inputs": ["TotalCharges", "tenure"],
      "semantic_rationale": "Cumulative charges divided by subscription duration approximate average monthly billing. This uses the corrected interpretation of tenure as subscription duration, likely in months. Return missing when tenure is zero or TotalCharges is missing; do not substitute zero.",
      "statistical_rationale": "Normalizes cumulative spending for customer exposure, separating historical billing intensity from subscription length. The billing identity suggests substantial redundancy with MonthlyCharges, so incremental value should be tested on held-out data.",
      "leakage_assessment": "possible",
      "business_interpretation": "Approximate historical monthly customer spend, provided the inputs were recorded before the prediction cutoff rather than updated after departure."
    },
    {
      "name": "current_rate_lifetime_exposure",
      "op": "product",
      "inputs": ["tenure", "MonthlyCharges"],
      "semantic_rationale": "Estimates cumulative charges if the current monthly rate had applied throughout the subscription. It is an approximation, not actual lifetime revenue.",
      "statistical_rationale": "Explicitly represents the interaction between subscription duration and current billing level. It may be redundant with TotalCharges under the documented billing rule; retain only if leakage-safe validation shows incremental value.",
      "leakage_assessment": "possible",
      "business_interpretation": "A current-rate measure of subscription exposure. It must use tenure and charges available at the intended scoring time."
    },
    {
      "name": "log_subscription_tenure",
      "op": "log1p",
      "inputs": ["tenure"],
      "semantic_rationale": "Represents subscription duration on a compressed scale while preserving zero-tenure customers.",
      "statistical_rationale": "Emphasizes differences early in the customer lifecycle and compresses differences among long-tenured customers. A monotonic transform may add little for gradient-boosted trees, so improvement should not be assumed.",
      "leakage_assessment": "possible",
      "business_interpretation": "Customer lifecycle maturity, not customer age. Tenure must be measured at the pre-outcome scoring cutoff."
    },
    {
      "name": "zero_tenure_customer",
      "op": "is_zero",
      "inputs": ["tenure"],
      "semantic_rationale": "Flags snapshots with no completed subscription-duration units. These could represent newly activated customers or a recording convention requiring confirmation.",
      "statistical_rationale": "Isolates a boundary population and helps distinguish undefined per-tenure ratios from ordinary billing values. Its usefulness depends on the number and consistency of zero-tenure observations.",
      "leakage_assessment": "possible",
      "business_interpretation": "Potential onboarding-stage customer indicator, subject to confirming tenure semantics and pre-outcome availability."
    }
  ],
  "candidate_judgements": {
    "cand_charges_per_month_of_tenure": {
      "decision": "accept",
      "reason": "Accept as TotalCharges / tenure: it has a defensible interpretation as historical average monthly billing, despite its modest development AUC. Confirm the recipe, treat zero tenure and missing TotalCharges as undefined, and verify pre-outcome availability. Its likely redundancy with MonthlyCharges should be assessed through held-out ablation."
    },
    "cand_price_increase_ratio": {
      "decision": "accept",
      "reason": "Accept under the interpretation MonthlyCharges / (TotalCharges / tenure), using only pre-outcome billing values and valid positive denominators. This measures current charges relative to historical average charges, not a verified price increase: bundle changes, discounts, and billing conventions could also explain it. Confirm the actual recipe and validate incremental value rather than relying on development AUC."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "record_key is a unique warehouse identifier excluded from modeling. Its exceptionally strong association suggests an extraction artifact or leakage; taking its logarithm preserves that information without creating a legitimate customer attribute."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "save_desk_outcome has disposition-like categories inconsistent with its documentation and may be recorded during or after retention or departure events. A flag derived from it inherits the suspected post-outcome leakage."
    },
    "cand_friday": {
      "decision": "reject",
      "reason": "Warehouse loading weekday is an operational artifact, not established customer behavior available at a meaningful prediction cutoff. Its association could reflect outcome-dependent extraction or batch processing and may not generalize."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "Computing target means on the full table exposes evaluation labels and contaminates validation, regardless of the weak AUC. A separate implementation could use out-of-fold training encodings and training-only mappings for evaluation, with smoothing and appropriate customer or temporal boundaries."
    }
  }
}
